251	    public boolean isHouseholdInUse(String lastName, String address, Integer excludeId) throws DataAccessException {
252	        for (Owner existing : ownerRepository.findAll()) {
253	            if (excludeId != null && excludeId.equals(existing.getId())) {
254	                continue;
255	            }
256	            if (sameHousehold(lastName, address, existing)) {
257	                return true;
258	            }
259	        }
260	        return false;
261	    }
262	
263	    @Override
264	    @Transactional
265	    public void assignHousehold(Owner owner) throws DataAccessException {
266	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
267	        owner.setHouseholdId(householdId);
268	        for (Owner existing : ownerRepository.findAll()) {
269	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
270	                continue;
271	            }
272	            if (sameHousehold(owner.getLastName(), owner.getAddress(), existing)
273	                && !householdId.equals(existing.getHouseholdId())) {
274	                existing.setHouseholdId(householdId);
275	                ownerRepository.save(existing);
276	            }
277	        }
278	    }
279	
280	    /**
281	     * Whether {@code other} belongs to the same household as an owner with the given last name and
282	     * address, i.e. both match case-insensitively with collapsed whitespace. This single definition
283	     * of "same household" backs both {@link #isHouseholdInUse} and {@link #assignHousehold}.
284	     */
285	    private static boolean sameHousehold(String lastName, String address, Owner other) {
286	        return normalizeForHousehold(lastName).equals(normalizeForHousehold(other.getLastName()))
287	            && normalizeForHousehold(address).equals(normalizeForHousehold(other.getAddress()));
288	    }
289	
290	    /**
291	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
292	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
293	     * two last names or addresses that differ only in case or whitespace be treated as equal.
294	     *
